import assert from 'node:assert/strict';
import { mock } from 'node:test';
import { readFile, writeFile } from 'node:fs/promises';
import { JSDOM } from 'jsdom';

const markdown = await readFile(new URL('../../../docs/application-composition.md', import.meta.url), 'utf8');
const code = markdown.split('<!-- executable-example: application-feed-composition -->')[1]
  .match(/^\s*```javascript\n([\s\S]*?)\n```/)[1];
const apiCode = markdown.split('<!-- executable-example: application-feed-api -->')[1]
  .match(/^\s*```javascript\n([\s\S]*?)\n```/)[1];
await writeFile(new URL('./dist/feed-api.js', import.meta.url), apiCode);
const { feedApi } = await import('./dist/feed-api.js');
const signal = new AbortController().signal;
const response = { items: [{ id: 1, title: 'Transport' }], hasNext: false };
const fetchMock = mock.method(globalThis, 'fetch', async(url, options) => {
  assert.equal(url, '/api/feed?page=2');
  assert.equal(options.signal, signal);
  return { ok: true, json: async() => response };
});
assert.deepEqual(await feedApi.loadPage(2, { signal }), response);
fetchMock.mock.mockImplementation(async() => ({ ok: false, status: 503 }));
await assert.rejects(feedApi.loadPage(2, { signal }), /503/);
fetchMock.mock.restore();
const file = new URL('./dist/feed.mjs', import.meta.url);
await writeFile(file, code);
const { RootApplication } = await import(file);
const { View } = await import('marionette');
const dom = new JSDOM('<main></main>');
globalThis.window = dom.window;
globalThis.document = dom.window.document;
const requests = [];
const errors = [];
mock.method(feedApi, 'loadPage', (page, { signal }) => {
  const request = { page, signal, ...Promise.withResolvers() };
  requests.push(request);
  return request.promise;
});
mock.method(console, 'error', error => errors.push(error));
const root = new RootApplication({ region: { el: document.querySelector('main') } });
const feed = root.getChildApp('feed');
const settle = () => new Promise(resolve => setImmediate(resolve));
try {
  const starting = root.start();
  assert.equal(feed.isRunning(), false);
  assert.equal(document.querySelector('[role=status]').textContent, 'Loading…');
  requests[0].reject(new Error('Initial load unavailable'));
  assert.equal(await starting, true, 'the feature intentionally activates a retry screen');
  assert.equal(feed.isRunning(), true);
  document.querySelector('[data-retry]').click();
  assert.equal(requests[1].page, 1, 'retry intent travels from View to Application');
  requests[1].resolve({ items: [{ id: 1, title: '<First>' }], hasNext: true });
  await settle();
  const feedView = feed.getView();
  const list = feedView.getChildView('articles');
  const row = list.children.findByModel(feed.articles.get(1));
  const textarea = document.querySelector('textarea');
  textarea.value = 'Keep my draft';
  document.querySelector('[data-next]').click();
  assert.equal(requests[2].page, 2);
  const newest = feed.refresh(3);
  assert.equal(requests[2].signal.aborted, true);
  requests[3].resolve({ items: [{ id: 1, title: 'Updated' }, { id: 2, title: 'Second' }], hasNext: false });
  assert.equal(await newest, true);
  requests[2].reject(new Error('Obsolete failure'));
  await settle();
  assert.equal(feed.getView(), feedView);
  assert.equal(list.children.findByModel(feed.articles.get(1)), row);
  assert.equal(document.querySelector('textarea'), textarea);
  assert.equal(textarea.value, 'Keep my draft');
  assert.equal(document.querySelector('[role=status]').textContent, 'Page 3');
  feed.articles.get(1).set('title', 'External update');
  assert.equal(row.el.textContent, 'External update');
  feed.getState().set('status', 'loading');
  assert.equal(document.querySelector('[role=status]').textContent, 'Loading…');
  const failed = feed.refresh(4);
  requests[4].reject(new Error('Page unavailable'));
  assert.equal(await failed, false);
  document.querySelector('[data-retry]').click();
  assert.equal(requests[5].page, 4, 'retry repeats requested page, not displayed page');
  requests[5].resolve({ items: [{ id: 1, title: 'Retried' }], hasNext: false });
  await settle();
  const pending = feed.refresh(5);
  await root.stop();
  assert.equal(requests[6].signal.aborted, true);
  requests[6].resolve({ items: [], hasNext: false });
  assert.equal(await pending, false);
  assert.equal(feed.articles.isDestroyed(), false);
  assert.equal(document.querySelector('main').children.length, 0);
  const restarting = root.start();
  requests[7].resolve({ items: [{ id: 1, title: 'Restarted' }], hasNext: true });
  await restarting;
  const late = feed.refresh(2);
  feed.getRegion().show(new View({ template: () => 'Replacement' }));
  requests[8].resolve({ items: [], hasNext: false });
  assert.equal(await late, false);
  await settle();
  assert.equal(feed.isRunning(), false);
  assert.equal(document.querySelector('[data-feed]').textContent, 'Replacement');
  await root.destroy();
  assert.equal(feed.isDestroyed(), true);
  assert.equal(feed.articles.isDestroyed(), true);
  assert.deepEqual(errors, []);
} finally {
  requests.forEach(request => request.resolve({ items: [], hasNext: false }));
  await root.destroy();
  mock.restoreAll();
  dom.window.close();
  delete globalThis.window;
  delete globalThis.document;
}
console.log('Feed composition passed: startup/retry intent, observable updates, identity, stale requests, parent/host cleanup.');
